*{box-sizing:border-box}
:root{color-scheme:dark;--page:#171717;--window:#383838;--window-light:#565656;--window-dark:#222;--panel:#303030;--panel-inset:#252525;--line:#555;--text:#e4e0d5;--muted:#aaa69b;--gold:#e3c878;--green:#73ad65;--red:#bd5d55;--blue:#6c9fca;--mono:"DM Mono",monospace;--sans:"DM Sans",Tahoma,sans-serif}
html{min-width:320px;background:var(--page);scroll-behavior:smooth}
body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 38% 0,#343434 0,#222 48%,#171717 100%);color:var(--text);font:13px var(--sans)}
button,select{font:inherit;color:inherit}button{cursor:pointer}button:focus-visible,select:focus-visible,a:focus-visible{outline:2px solid #e8cf81;outline-offset:2px}
.client-window{width:min(1580px,100%);min-height:100vh;margin:auto;padding:12px 16px 22px}
.client-titlebar{height:42px;display:flex;align-items:center;justify-content:space-between;padding:0 10px 0 14px;border:1px solid #747474;border-bottom-color:#1c1c1c;background:linear-gradient(#4b4b4b,#303030);box-shadow:inset 1px 1px #777,inset -1px -1px #222;color:#e8e4d9}
.client-brand{display:flex;align-items:center;gap:9px;min-width:0}.client-brand strong{font:700 12px var(--mono);letter-spacing:1.3px}.brand-gem{color:var(--gold);font-size:19px;text-shadow:0 0 8px #d5ab45}.client-version{margin-left:4px;color:#c5c0b3;font:8px var(--mono);letter-spacing:1px}
.window-actions{display:flex;align-items:center;gap:5px}.window-actions button{height:25px;min-width:28px;padding:0 7px;border:1px solid #777;border-right-color:#222;border-bottom-color:#222;background:linear-gradient(#515151,#353535);color:#e1ddcf;font:9px var(--mono)}.window-actions button:hover{background:#626262}.window-actions #helpBtn{font-weight:bold;font-size:12px}
.client-layout{display:grid;grid-template-columns:minmax(0,1fr) 286px;align-items:start;gap:9px;margin-top:9px}
.world-window,.dock-panel{min-width:0;border:1px solid #737373;border-right-color:#1d1d1d;border-bottom-color:#1d1d1d;background:linear-gradient(145deg,#454545,#303030 65%);box-shadow:inset 1px 1px #696969,inset -1px -1px #242424}
.world-toolbar{height:35px;display:flex;align-items:center;gap:9px;padding:0 8px;border-bottom:1px solid #202020;background:linear-gradient(#4c4c4c,#373737);color:#dbd6ca;font:9px var(--mono);letter-spacing:.65px}.location-mark{color:var(--gold);font-size:16px}.world-toolbar>strong{color:#e8d69c;font-size:9px}.toolbar-divider{height:15px;width:1px;background:#707070}.toolbar-actions{display:flex;align-items:center;gap:5px;margin-left:auto}.toolbar-actions>button{height:23px;padding:0 7px;border:1px solid #777;border-right-color:#222;border-bottom-color:#222;background:#363636;color:#ddd8cb;font:8px var(--mono);white-space:nowrap}.toolbar-actions>button:hover{background:#505050}.status-light{width:6px;height:6px;border-radius:50%;background:#79ba60;box-shadow:0 0 6px #79ba60}
.game-frame{position:relative;width:100%;height:clamp(380px,calc(100vh - 150px),760px);min-height:340px;overflow:hidden;background:#192417;border:3px solid #252525;box-shadow:inset 0 0 0 1px #777;isolation:isolate}.game-frame canvas{display:block;width:100%;height:100%;image-rendering:pixelated;touch-action:none}.frame-vignette{position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 34px #06070666}.game-top-hud{position:absolute;z-index:2;top:10px;left:10px;right:10px;display:flex;align-items:flex-start;justify-content:space-between;pointer-events:none}.round-pill{height:27px;padding:0 9px;display:flex;align-items:center;border:1px solid #b2a57a88;background:#171914d9;box-shadow:0 2px 6px #0008;color:#e6d9ac;font:8px var(--mono);letter-spacing:.7px}.round-pill span{margin-right:6px;color:var(--gold);font-size:14px}.kill-progress{height:27px;padding:0 9px;display:flex;align-items:center;border:1px solid #b2a57a66;background:#171914d9;box-shadow:0 2px 6px #0008;color:#f0d998;font:8px var(--mono);letter-spacing:.6px}.kill-feed{position:absolute;z-index:2;top:49px;left:10px;display:grid;gap:4px;max-width:min(330px,65%);pointer-events:none}.feed-line{display:flex;gap:4px;align-items:center;padding:5px 8px;border:1px solid #bcb18440;background:#151713ce;color:#d9d4c7;font-size:10px;line-height:1.3}.feed-line b{color:#f0d998}.feed-gold{color:var(--gold)}.canvas-tip{position:absolute;z-index:2;right:8px;bottom:7px;padding:5px 7px;border:1px solid #bcb18438;background:#141611c9;color:#b8b4a7;font:8px var(--mono);pointer-events:none}.canvas-tip span{color:#f0d997}.canvas-tip i{padding:0 3px;color:#777}.world-statusbar{height:24px;display:flex;justify-content:space-between;align-items:center;padding:0 8px;border-top:1px solid #777;background:#292929;color:#aaa79d;font:8px var(--mono);letter-spacing:.45px}.world-statusbar>span:first-child{display:flex;align-items:center;gap:6px}.status-light{width:5px;height:5px}
.right-dock{position:relative;display:grid;gap:7px;min-width:0}.dock-panel{padding:9px 10px 10px;background:linear-gradient(145deg,#3b3b3b,#303030)}.panel-title{min-height:18px;display:flex;align-items:center;justify-content:space-between;gap:6px;margin:0 0 8px;padding:0 0 6px;border-bottom:1px solid #585858;color:#ded9cc;font:700 9px var(--mono);letter-spacing:.8px}.panel-mark{color:var(--gold);font-size:13px}.character-summary{display:flex;align-items:center;gap:10px}.character-paperdoll{width:58px;height:70px;flex:none;display:grid;place-items:center;align-content:center;gap:3px;border:1px solid #181818;outline:1px solid #666;background:radial-gradient(ellipse,#555 0,#333 62%,#252525 100%);box-shadow:inset 0 0 0 2px #3f3f3f;color:#d5c28d}.character-paperdoll>span{font-size:32px;text-shadow:0 2px 5px #111}.character-paperdoll small{color:#aaa28d;font:7px var(--mono)}.character-info{min-width:0;display:grid;gap:3px}.character-info select{max-width:100%;height:23px;padding:0 20px 0 5px;border:1px solid #7d6a40;background:#282722;color:#e5d39a;font:700 8px var(--mono);letter-spacing:.55px}.hero-class{display:none}.hero-name{overflow:hidden;color:#e9e3d3;font-size:11px;font-weight:600;text-overflow:ellipsis;white-space:nowrap}.character-faction{color:#9eafc0;font:7px var(--mono);letter-spacing:.5px}.resource-block{display:grid;gap:2px;margin-top:11px}.resource-row{display:flex;justify-content:space-between;align-items:center;margin-top:3px;color:#b8b3a7;font:8px var(--mono);letter-spacing:.6px}.resource-row b{color:#e7e2d7;font:8px var(--mono);letter-spacing:0}.health-track,.mana-track{height:9px;width:100%;margin-top:2px;overflow:hidden;border:1px solid #171717;background:#1f1f1f;box-shadow:inset 0 1px 2px #000}.health-track i,.mana-track i{display:block;width:100%;height:100%;transition:width .18s ease}.health-track i{background:linear-gradient(#bd7163,#963d34)}.mana-track i{background:linear-gradient(#6ba5c4,#356c95)}.character-stats{display:flex;justify-content:space-between;gap:6px;margin-top:10px;padding-top:7px;border-top:1px solid #555;color:#aaa69a;font:7px var(--mono);letter-spacing:.3px}.character-stats b{display:block;margin-top:3px;color:#e5d49e;font-size:8px;letter-spacing:0}.character-stats b i{color:#9d988a;font-style:normal}
.target-panel{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;column-gap:8px}.target-panel .panel-title{grid-column:1/-1;width:100%;margin-bottom:7px}.target-copy{display:grid;gap:4px;min-width:0}.target-copy strong{overflow:hidden;color:#e7d79d;font-size:11px;text-overflow:ellipsis;white-space:nowrap}.target-copy span{color:#aaa69a;font:7px var(--mono);letter-spacing:.25px}.attack-button{min-height:33px;display:flex;align-items:center;gap:5px;padding:0 7px;border:1px solid #8e7847;border-right-color:#2b2416;border-bottom-color:#2b2416;background:linear-gradient(#51452b,#332d20);color:#f0d794;white-space:nowrap}.attack-button:hover:not(:disabled){background:linear-gradient(#655632,#443a25)}.attack-button:disabled{cursor:not-allowed;filter:grayscale(.8);opacity:.48}.attack-button span{font-size:14px}.attack-button b{font:700 8px var(--mono);letter-spacing:.4px}.attack-button kbd{padding:2px 4px;border:1px solid #8c794f;color:#e8d699;font:7px var(--mono)}
.spell-loadout{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:5px}.spell-slot{position:relative;min-width:0;height:69px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;padding:12px 3px 4px;border:1px solid #686252;border-right-color:#202020;border-bottom-color:#202020;background:linear-gradient(#414039,#292925);text-align:center;transition:border-color .15s,background .15s,opacity .15s}.spell-slot:hover:not(:disabled),.spell-slot:focus-visible{border-color:#d0b76b;background:#484431;outline:none}.spell-slot:disabled{cursor:not-allowed;opacity:.5}.spell-slot.unavailable{filter:saturate(.6)}.spell-slot.active-spell,.spell-slot[aria-pressed=true]{border-color:#e1c273;background:#49432f;box-shadow:inset 0 0 0 1px #8e774a,0 0 8px #d5ae6626}.spell-slot kbd{position:absolute;top:3px;left:4px;min-width:14px;padding:1px 3px;border:1px solid #777052;color:#e5d394;text-align:center;font:7px var(--mono)}.spell-icon{color:#e3ca7e;font-size:17px;font-weight:400;line-height:18px}.spell-name{width:100%;overflow:hidden;color:#e4e0d5;font-size:8px;font-weight:600;text-overflow:ellipsis;white-space:nowrap}.spell-cost{color:#91bad0;font:7px var(--mono);white-space:nowrap}.spell-slot.cooling:after{position:absolute;inset:0;display:grid;place-items:center;content:'⌛';background:#15151588;color:#fff;font-size:18px}.spell-slot[aria-pressed=true]:after{content:'LISTO';position:absolute;top:3px;right:3px;inset:auto;color:#f1d88a;font:6px var(--mono);letter-spacing:.3px}.spell-hint{margin:6px 0 0;color:#aaa699;font:7px var(--mono);line-height:1.4;text-align:center}
.inventory-capacity,.roster-count{color:#b9ae89;font:7px var(--mono);letter-spacing:.25px;white-space:nowrap}.inventory-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:4px}.inventory-slot{aspect-ratio:1;min-width:0;border:1px solid #161616;outline:1px solid #5a5a5a;background:linear-gradient(145deg,#303030,#292929);box-shadow:inset 1px 1px #3b3b3b}.inventory-slot:hover{background:#383838}.inventory-note{margin:7px 0 0;color:#a9a497;font:7px var(--mono);line-height:1.35}.equipment-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:5px}.equipment-slot{aspect-ratio:1;display:grid;place-items:center;align-content:center;gap:3px;border:1px solid #171717;outline:1px solid #5c5c5c;background:#292929;color:#b9a875}.equipment-slot span{font-size:16px}.equipment-slot small{color:#a7a294;font:6px var(--mono)}
.side-panel{position:absolute;z-index:5;top:0;right:calc(100% + 8px);width:260px;max-height:calc(100vh - 90px);overflow:auto;border:1px solid #777;background:#2c2c2c;box-shadow:0 8px 26px #000b}.side-panel.hidden{display:none}.roster-section,.battle-log{padding:10px}.roster{display:grid}.roster-row{width:100%;min-height:39px;display:flex;align-items:center;gap:7px;padding:4px 3px;border:0;border-bottom:1px solid #4b4b4b;background:transparent;color:inherit;text-align:left}.roster-row:hover,.roster-row:focus-visible{background:#414141;outline:none}.roster-row.targeted{background:#464130;box-shadow:inset 2px 0 #e3c878}.roster-row.fighter-dead{opacity:.42}.roster-avatar{width:25px;height:25px;flex:none;display:grid;place-items:center;border:1px solid #666;background:#383838;color:#dfc77c;font-size:14px}.roster-copy{min-width:0;flex:1;display:grid;gap:2px}.roster-copy b{overflow:hidden;font-size:9px;text-overflow:ellipsis;white-space:nowrap}.roster-copy b.name-sacred{color:#8ec7e9}.roster-copy b.name-chaotic{color:#e57a6d}.roster-copy small{color:#aaa69a;font:6px var(--mono)}.battle-log{border-top:1px solid #575757}.log-items{display:grid;gap:5px;color:#c3bfb2;font-size:9px}.empty-log{color:#9d998e;font-size:8px}.log-entry{padding:4px 5px;border-left:2px solid #877849;background:#252525;font-size:8px}.roster-row[data-fighter]:not(.self-row){cursor:pointer}.roster-row.self-row{cursor:default}
.mobile-joystick,.mobile-cast-hint{display:none}.respawn-notice{position:absolute;z-index:3;top:50%;left:50%;display:grid;gap:6px;min-width:190px;padding:13px 18px;transform:translate(-50%,-50%);border:1px solid #d5bd79;background:#151711eF;box-shadow:0 6px 24px #000b;text-align:center;pointer-events:none}.respawn-notice strong{color:#e4c87e;font:700 13px var(--mono);letter-spacing:1.4px}.respawn-notice span{color:#d8d3c4;font-size:11px}.respawn-notice b{color:#fff0bd;font:700 13px var(--mono)}.hidden{display:none!important}.toast{position:fixed;z-index:20;left:50%;bottom:22px;max-width:min(90vw,480px);padding:10px 15px;transform:translate(-50%,20px);border:1px solid #88794d;background:#25251feF;color:#f0e2b9;font-size:11px;opacity:0;pointer-events:none;transition:opacity .2s,transform .2s}.toast.show{transform:translate(-50%,0);opacity:1}
.client-footer{display:flex;justify-content:space-between;gap:12px;margin:8px 2px 0;color:#969287;font:8px var(--mono);letter-spacing:.45px}.client-footer a{color:#d8c27d;text-decoration:underline;text-underline-offset:2px}.project-roadmap{margin:24px 0 0;padding:20px;border:1px solid #565656;background:linear-gradient(145deg,#303030,#242424);box-shadow:0 12px 30px #08080866}.roadmap-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:18px;margin-bottom:12px}.roadmap-kicker{color:#c7ae69;font:8px var(--mono);letter-spacing:1.3px}.project-roadmap h1{margin:6px 0 0;color:#e8e4d8;font-size:24px;font-weight:600}.roadmap-version{padding:7px 9px;border:1px solid #625a44;background:#302e27;color:#d3c28e;font:7px var(--mono);letter-spacing:.7px;white-space:nowrap}.roadmap-intro{max-width:1000px;margin:0 0 14px;color:#bbb7ab;font-size:11px;line-height:1.65}.roadmap-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.roadmap-card{min-width:0;padding:12px;border:1px solid #4b4b4b;background:#292929}.roadmap-card h2{margin:0 0 9px;color:#e2d39d;font:700 9px var(--mono);letter-spacing:.65px}.roadmap-card ul{display:grid;gap:6px;margin:0;padding:0;list-style:none}.roadmap-card li{position:relative;padding-left:13px;color:#b7b3a8;font-size:10px;line-height:1.5}.roadmap-card li:before{position:absolute;left:2px;color:#c0ae70;content:'·';font-size:15px;line-height:12px}.roadmap-card li.in-progress:before{content:'◉';font-size:9px;line-height:14px}.roadmap-card code{padding:1px 4px;border:1px solid #555;background:#202020;color:#d6c58e;font:8px var(--mono)}.roadmap-wide{grid-column:1/-1}
.modal{position:fixed;z-index:30;inset:0;display:grid;place-items:center;padding:16px;background:#000a}.modal.hidden{display:none}.modal-card{position:relative;width:min(440px,100%);padding:20px;border:1px solid #777;background:linear-gradient(#3c3c3c,#292929);box-shadow:0 14px 40px #000b}.modal-card h2{margin:0 0 14px;color:#e6d59d;font:700 14px var(--mono);letter-spacing:.5px}.modal-close{position:absolute;right:9px;top:7px;border:0;background:transparent;color:#ddd;font-size:22px}.control-list{display:grid;gap:8px}.control-list p{display:grid;grid-template-columns:120px 1fr;align-items:center;gap:8px;margin:0;color:#c9c5ba;font-size:10px}.control-list kbd{padding:5px;border:1px solid #777;background:#292929;color:#e6d79e;text-align:center;font:8px var(--mono)}.modal-note{margin-top:13px;padding-top:10px;border-top:1px solid #555;color:#aaa69a;font-size:9px;line-height:1.5}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
@media(max-width:1100px){.client-layout{grid-template-columns:minmax(0,1fr) 260px}.client-window{padding-right:10px;padding-left:10px}.game-frame{height:clamp(350px,calc(100vh - 145px),700px)}.side-panel{width:240px}}
@media(max-width:760px){.client-window{padding:7px 7px 18px}.client-titlebar{height:38px;padding:0 7px}.client-brand{gap:6px}.client-brand strong{font-size:10px;letter-spacing:.7px}.brand-gem{font-size:16px}.client-version{font-size:7px}.window-actions{gap:3px}.window-actions button{height:23px;padding:0 5px;font-size:8px}.client-layout{display:flex;flex-direction:column;gap:8px}.world-window,.right-dock{width:100%}.world-toolbar{height:33px;gap:6px;padding:0 5px;font-size:7px}.world-toolbar>strong{font-size:7px}.toolbar-actions{gap:3px}.toolbar-actions>button{height:22px;padding:0 4px;font-size:7px}.game-frame{height:min(64vh,560px);min-height:320px}.game-top-hud{top:7px;left:6px;right:6px}.round-pill{height:23px;padding:0 6px;font-size:6px}.round-pill span{margin-right:3px}.kill-progress{height:23px;padding:0 6px;font-size:6px}.kill-feed{top:39px;left:6px;max-width:70%}.feed-line{padding:4px 5px;font-size:8px}.canvas-tip{display:none}.mobile-joystick{position:absolute;z-index:3;left:13px;bottom:14px;width:92px;height:92px;display:block;touch-action:none}.joy-ring{position:absolute;inset:0;display:grid;place-items:center;border:1px solid #eee0a877;border-radius:50%;background:#10180fa1;box-shadow:inset 0 0 0 7px #d6d2b515}.joy-knob{width:37px;height:37px;border:1px solid #e4d59b;border-radius:50%;background:#b9aa7555;box-shadow:0 1px 5px #0008}.mobile-cast-hint{position:absolute;right:10px;bottom:14px;display:block;padding:5px 7px;border:1px solid #ddd2a344;background:#10150fc9;color:#e2d6aa;font:7px var(--mono)}.world-statusbar{font-size:7px}.right-dock{grid-template-columns:repeat(2,minmax(0,1fr));align-items:start;gap:7px}.character-panel,.skills-panel{grid-column:1/-1}.character-panel{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);column-gap:12px}.character-panel>.panel-title{grid-column:1/-1}.character-summary{grid-row:2;grid-column:1}.resource-block{grid-row:2;grid-column:2;margin-top:0;align-self:center}.character-stats{grid-column:1/-1}.target-panel{grid-column:1/-1}.inventory-panel,.equipment-panel{grid-column:span 1}.side-panel{position:static;grid-column:1/-1;width:100%;max-height:60vh}.client-footer{font-size:7px}.project-roadmap{margin-top:18px;padding:14px}.roadmap-heading{align-items:flex-start;flex-direction:column;gap:9px}.project-roadmap h1{font-size:21px}.roadmap-intro{font-size:10px}.roadmap-grid{grid-template-columns:1fr}.roadmap-wide{grid-column:auto}.roadmap-card{padding:11px}.roadmap-card li{font-size:9px}}
@media(max-width:420px){.client-brand strong{font-size:8px}.client-version{display:none}.world-toolbar{gap:4px}.world-toolbar>strong{font-size:6px;letter-spacing:.3px}.toolbar-divider{height:12px}.toolbar-actions>button{font-size:6px;padding:0 3px}.world-toolbar>span:not(.location-mark):not(.toolbar-divider){display:none}.game-frame{height:58vh;min-height:300px}.round-pill{font-size:0}.round-pill span{font-size:14px}.character-panel{column-gap:7px;padding:8px}.character-paperdoll{width:48px;height:62px}.character-info select{font-size:7px}.hero-name{font-size:10px}.character-stats{font-size:6px}.spell-slot{height:64px}.spell-name{font-size:7px}.spell-cost{font-size:6px}.client-footer{flex-direction:column;gap:5px}.control-list p{grid-template-columns:100px 1fr}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;transition:none!important}}

/* Classic-client pass: square, compact beveled panels keep the world and character sheet in view. */
:root{--page:#242424;--window:#4a4a4a;--window-light:#707070;--window-dark:#202020;--panel:#484848;--panel-inset:#303030;--line:#777;--text:#e5e5e5;--muted:#bcbcbc;--gold:#d5c78b;--green:#73ad65;--red:#bd5d55;--blue:#659fc2;--mono:"Lucida Console",Consolas,monospace;--sans:Tahoma,Verdana,sans-serif}
body{background:#242424;font-family:Tahoma,Verdana,sans-serif}
.client-window{width:min(1660px,100%);padding:8px 10px 20px}
.client-titlebar,.world-toolbar,.dock-panel,.world-window,.window-actions button,.toolbar-actions>button{border-radius:0;box-shadow:inset 1px 1px #888,inset -1px -1px #202020}
.client-titlebar{height:34px;background:linear-gradient(#666,#444);border-color:#929292;border-bottom-color:#1c1c1c}
.client-brand strong{font-family:Tahoma,Verdana,sans-serif;font-size:13px;letter-spacing:.5px}
.client-version{font:9px Tahoma,Verdana,sans-serif;letter-spacing:.3px}
.client-layout{grid-template-columns:minmax(0,1fr) 320px;gap:6px;margin-top:6px}
.world-window,.dock-panel{background:#494949;border-color:#898989;border-right-color:#1e1e1e;border-bottom-color:#1e1e1e}
.world-toolbar{height:29px;background:linear-gradient(#626262,#484848);font:10px Tahoma,Verdana,sans-serif;letter-spacing:.2px}
.world-toolbar>strong{font:700 10px Tahoma,Verdana,sans-serif;color:#f0e2ad}
.world-toolbar .location-mark{font-size:15px}
.toolbar-actions>button{font:9px Tahoma,Verdana,sans-serif}
.game-frame{height:clamp(420px,calc(100vh - 125px),820px);min-height:360px;border:2px solid #252525;box-shadow:inset 0 0 0 1px #898989}
.game-frame canvas{image-rendering:pixelated}
.game-top-hud{top:7px;left:7px;right:7px}
