1: *{box-sizing:border-box}
2: :root{color-scheme:dark;--page:#171717;--window:#383838;--window-light:#565656;--window-dark:#222;--panel:#303030;--panel-inset:#252525;--line:#555;--text:#e4e0d5;--muted:#aaa69b;--gold:#e3c878;--green:#73ad65;--red:#bd5d55;--blue:#6c9fca;--mono:"DM Mono",monospace;--sans:"DM Sans",Tahoma,sans-serif}
3: html{min-width:320px;background:var(--page);scroll-behavior:smooth}
